import { MastraReactProvider } from '@mastra/react';
import { QueryClient, QueryClientProvider } from '@tanstack/react-query';
import { cleanup, fireEvent, render, waitFor } from '@testing-library/react';
import { http, HttpResponse } from 'msw';
import type { ReactNode } from 'react';
import { FormProvider, useForm } from 'react-hook-form';
import { afterEach, beforeAll, beforeEach, describe, expect, it } from 'vitest';

// Base UI's Checkbox synthesizes a PointerEvent on click, which jsdom does not
// implement; alias it to MouseEvent so click handlers run.
beforeAll(() => {
  if (typeof window.PointerEvent === 'undefined') {
    window.PointerEvent = window.MouseEvent as unknown as typeof PointerEvent;
  }
});

import { AgentColorProvider } from '../../../../contexts/agent-color-context';
import type { AgentBuilderEditFormValues } from '../../../../schemas';
import { Models } from '../models';
import { buildAvailableModels, buildBuilderSettings } from './fixtures/builder';
import { server } from '@/test/msw-server';

const BASE_URL = 'http://localhost:4111';

/**
 * Backs the real picker data flow: `useBuilderModelPolicy` reads builder
 * settings (no `modelPolicy` ⇒ inactive ⇒ picker not locked) and
 * `useAgentBuilderAllowedModels` fetches the server-filtered model list.
 */
const registerModelHandlers = () => {
  server.use(
    http.get(`${BASE_URL}/api/editor/builder/settings`, () => HttpResponse.json(buildBuilderSettings())),
    http.get(`${BASE_URL}/api/editor/builder/models/available`, () => HttpResponse.json(buildAvailableModels())),
  );
};

const FormHarness = ({ agentId = 'agent_test', children }: { agentId?: string; children: ReactNode }) => {
  const queryClient = new QueryClient({ defaultOptions: { queries: { retry: false } } });
  const methods = useForm<AgentBuilderEditFormValues>({
    defaultValues: {
      model: { provider: 'openai', name: 'gpt-4o' },
    } as AgentBuilderEditFormValues,
  });
  return (
    <MastraReactProvider baseUrl={BASE_URL}>
      <QueryClientProvider client={queryClient}>
        <FormProvider {...methods}>
          <AgentColorProvider agentId={agentId}>{children}</AgentColorProvider>
        </FormProvider>
      </QueryClientProvider>
    </MastraReactProvider>
  );
};

/** Renders the picker and waits for the allowed-models query to resolve. */
const renderModels = async () => {
  const utils = render(
    <FormHarness>
      <Models />
    </FormHarness>,
  );
  await utils.findByTestId('model-card-picker');
  return utils;
};

describe('Models', () => {
  beforeEach(() => {
    registerModelHandlers();
  });

  afterEach(() => {
    cleanup();
  });

  describe('when an agentId is provided', () => {
    it('paints the selected model container with border-based HSL and no accent classes', async () => {
      const { getByTestId } = await renderModels();

      const container = getByTestId('model-card-openai-gpt-4o') as HTMLButtonElement;
      expect(container.style.borderColor).toMatch(/^(rgb|hsl)\(/);
      expect(container.style.boxShadow).toBe('');
      expect(container.className).toContain('focus-visible:!border-[var(--agent-color-bg)]');
      expect(container.className).not.toContain('border-accent1');
      expect(container.className).not.toContain('ring-1 ring-accent1');
      expect(container.className).not.toContain('focus-visible:ring');
    });

    it('paints the selected model check cell with border-based HSL', async () => {
      const { getByTestId } = await renderModels();

      const check = getByTestId('model-card-check-openai-gpt-4o') as HTMLSpanElement;
      expect(check.style.backgroundColor).toMatch(/^(rgb|hsl)\(/);
      expect(check.style.borderColor).toMatch(/^(rgb|hsl)\(/);
      expect(check.className).not.toContain('bg-accent1');
    });

    it('leaves unselected model borders untouched while using agent color for focus', async () => {
      const { getByTestId } = await renderModels();

      const container = getByTestId('model-card-anthropic-claude-3-5-sonnet') as HTMLButtonElement;
      expect(container.style.getPropertyValue('--agent-color-bg')).toMatch(/^hsl\(/);
      expect(container.style.borderColor).toBe('');
      expect(container.className).toContain('border-border1');
      expect(container.className).toContain('focus-visible:!border-[var(--agent-color-bg)]');
      expect(container.className).not.toContain('focus-visible:ring');
    });

    it('paints the checked provider checkbox with agent color', async () => {
      const { getByTestId } = await renderModels();

      const checkbox = getByTestId('models-provider-filter-checkbox-openai') as HTMLButtonElement;
      expect(checkbox.style.backgroundColor).toMatch(/^(rgb|hsl)\(/);
      expect(checkbox.style.borderColor).toMatch(/^(rgb|hsl)\(/);
      expect(checkbox.className).not.toContain('bg-accent1');
    });
  });

  describe('when rendering the model grid', () => {
    it('renders an uppercase text-neutral3 section title per provider', async () => {
      const { getByTestId } = await renderModels();

      const openaiTitle = getByTestId('model-provider-section-title-openai');
      expect(openaiTitle.textContent).toBe('OpenAI');
      expect(openaiTitle.className).toContain('text-neutral3');
      expect(openaiTitle.className).toContain('uppercase');
      expect(openaiTitle.className).toContain('text-ui-sm');

      const anthropicTitle = getByTestId('model-provider-section-title-anthropic');
      expect(anthropicTitle.textContent).toBe('Anthropic');
    });

    it('groups each provider card under its own section', async () => {
      const { getByTestId } = await renderModels();

      const openaiSection = getByTestId('model-provider-section-openai');
      const openaiCard = getByTestId('model-card-openai-gpt-4o');
      const anthropicCard = getByTestId('model-card-anthropic-claude-3-5-sonnet');
      expect(openaiSection.contains(openaiCard)).toBe(true);
      expect(openaiSection.contains(anthropicCard)).toBe(false);
    });
  });

  describe('when rendering the provider filter', () => {
    it('renders one filter row per provider, all checked by default', async () => {
      const { getByTestId } = await renderModels();

      expect(getByTestId('models-provider-filter-item-openai')).toBeTruthy();
      expect(getByTestId('models-provider-filter-item-anthropic')).toBeTruthy();
      expect(getByTestId('models-provider-filter-checkbox-openai').getAttribute('aria-checked')).toBe('true');
      expect(getByTestId('models-provider-filter-checkbox-anthropic').getAttribute('aria-checked')).toBe('true');
    });
  });

  describe('when a provider is unchecked', () => {
    it('hides that provider section and cards while keeping the others', async () => {
      const { getByTestId, queryByTestId } = await renderModels();

      fireEvent.click(getByTestId('models-provider-filter-checkbox-anthropic'));

      expect(queryByTestId('model-provider-section-anthropic')).toBeNull();
      expect(queryByTestId('model-card-anthropic-claude-3-5-sonnet')).toBeNull();
      expect(queryByTestId('model-provider-section-openai')).toBeTruthy();
      expect(queryByTestId('model-card-openai-gpt-4o')).toBeTruthy();
    });

    it('restores the provider when re-checked', async () => {
      const { getByTestId, queryByTestId } = await renderModels();

      fireEvent.click(getByTestId('models-provider-filter-checkbox-anthropic'));
      expect(queryByTestId('model-provider-section-anthropic')).toBeNull();

      fireEvent.click(getByTestId('models-provider-filter-checkbox-anthropic'));
      expect(queryByTestId('model-provider-section-anthropic')).toBeTruthy();
      expect(queryByTestId('model-card-anthropic-claude-3-5-sonnet')).toBeTruthy();
    });
  });

  describe('when using Clear all / Select all', () => {
    it('Clear all hides every provider section and shows the empty-state copy', async () => {
      const { getByTestId, getByText, queryByTestId } = await renderModels();

      fireEvent.click(getByTestId('models-provider-filter-clear-all'));

      expect(queryByTestId('model-provider-section-openai')).toBeNull();
      expect(queryByTestId('model-provider-section-anthropic')).toBeNull();
      expect(getByText('Select at least one provider to see models')).toBeTruthy();
    });

    it('Select all restores every provider section after clearing', async () => {
      const { getByTestId, queryByTestId } = await renderModels();

      fireEvent.click(getByTestId('models-provider-filter-clear-all'));
      expect(queryByTestId('model-provider-section-openai')).toBeNull();

      fireEvent.click(getByTestId('models-provider-filter-select-all'));
      expect(queryByTestId('model-provider-section-openai')).toBeTruthy();
      expect(queryByTestId('model-provider-section-anthropic')).toBeTruthy();
    });
  });

  describe('when searching', () => {
    it('the left-pane search filters the provider checklist without affecting the model grid', async () => {
      const { getByTestId, queryByTestId } = await renderModels();

      const filterSearch = getByTestId('models-provider-filter-search').querySelector('input');
      expect(filterSearch).toBeTruthy();
      fireEvent.change(filterSearch!, { target: { value: 'anthropic' } });

      await waitFor(() => expect(queryByTestId('models-provider-filter-item-openai')).toBeNull());
      expect(queryByTestId('models-provider-filter-item-anthropic')).toBeTruthy();

      // Model grid is unaffected by the left-pane search.
      expect(queryByTestId('model-provider-section-openai')).toBeTruthy();
      expect(queryByTestId('model-card-openai-gpt-4o')).toBeTruthy();
    });

    it('combines provider filter and search to yield the search empty state', async () => {
      const { getByTestId, findByText } = await renderModels();

      fireEvent.click(getByTestId('models-provider-filter-checkbox-anthropic'));

      const searchInput = getByTestId('model-card-picker-search').querySelector('input');
      expect(searchInput).toBeTruthy();
      fireEvent.change(searchInput!, { target: { value: 'claude' } });

      await findByText('No models match "claude"');
    });
  });
});

import { TooltipProvider } from '@mastra/playground-ui/components/Tooltip';
import { MastraReactProvider } from '@mastra/react';
import { QueryClient, QueryClientProvider } from '@tanstack/react-query';
import { act, cleanup, render, waitFor } from '@testing-library/react';
import { http, HttpResponse } from 'msw';
import type { ReactNode } from 'react';
import { FormProvider, useForm } from 'react-hook-form';
import { MemoryRouter } from 'react-router';
import { afterEach, beforeEach, describe, expect, it } from 'vitest';

import { AgentColorProvider } from '../../../contexts/agent-color-context';
import { CREATE_SKILL_TOOL_NAME } from '../../../hooks/use-create-skill-tool';
import type { AgentBuilderEditFormValues } from '../../../schemas';
import {
  SET_AGENT_BROWSER_ENABLED_TOOL_NAME,
  SET_AGENT_DESCRIPTION_TOOL_NAME,
  SET_AGENT_INSTRUCTIONS_TOOL_NAME,
  SET_AGENT_MODEL_TOOL_NAME,
  SET_AGENT_NAME_TOOL_NAME,
  SET_AGENT_SKILLS_TOOL_NAME,
  SET_AGENT_TOOLS_TOOL_NAME,
  SET_AGENT_WORKSPACE_ID_TOOL_NAME,
} from '../../../services/tool-constants';
import type { AgentTool } from '../../../types/agent-tool';
import { ConversationPanel } from '../conversation-panel';
import { authDisabledCapabilities, emptyThreadMessages, openAiOnlyModels } from './fixtures/conversation';
import { server } from '@/test/msw-server';

const BASE_URL = 'http://localhost:4111';
const AGENT_ID = 'agent-test';
const BUILDER_THREAD_ID = `agent-builder-${AGENT_ID}`;

type Features = {
  tools: boolean;
  memory: boolean;
  workflows: boolean;
  agents: boolean;
  avatarUpload: boolean;
  skills: boolean;
  model: boolean;
  favorites: boolean;
  browser: boolean;
};

const allOff: Features = {
  tools: false,
  memory: false,
  workflows: false,
  agents: false,
  avatarUpload: false,
  skills: false,
  model: false,
  favorites: false,
  browser: false,
};

type WireTool = { id?: string; description?: string };
type StreamBody = {
  memory?: { thread?: string };
  clientTools?: Record<string, WireTool>;
  instructions?: string;
  messages?: Array<{ content?: unknown }>;
};

/** Closes immediately so useChat completes without producing messages. */
const emptyStream = () =>
  new ReadableStream<Uint8Array>({
    start(controller) {
      controller.close();
    },
  });

const sseResponse = () =>
  new HttpResponse(emptyStream(), { status: 200, headers: { 'content-type': 'text/event-stream' } });

const toAgentTools = (tools: Array<{ id: string; description?: string; type?: AgentTool['type'] }>): AgentTool[] =>
  tools.map(t => ({
    id: t.id,
    name: t.id,
    description: t.description,
    isChecked: false,
    type: t.type ?? 'tool',
  }));

const Wrapper = ({ children }: { children: ReactNode }) => {
  const methods = useForm<AgentBuilderEditFormValues>({
    defaultValues: { name: 'Initial', instructions: '', tools: {} },
  });
  const queryClient = new QueryClient({ defaultOptions: { queries: { retry: false } } });
  return (
    <MastraReactProvider baseUrl={BASE_URL}>
      <QueryClientProvider client={queryClient}>
        <TooltipProvider>
          <MemoryRouter>
            <FormProvider {...methods}>
              <AgentColorProvider agentId={AGENT_ID}>{children}</AgentColorProvider>
            </FormProvider>
          </MemoryRouter>
        </TooltipProvider>
      </QueryClientProvider>
    </MastraReactProvider>
  );
};

interface RenderOptions {
  features?: Features;
  availableTools?: Array<{ id: string; description?: string; type?: AgentTool['type'] }>;
  availableWorkspaces?: Array<{ id: string; name: string }>;
}

const renderPanel = ({ features = allOff, availableTools = [], availableWorkspaces = [] }: RenderOptions = {}) =>
  render(
    <ConversationPanel
      initialUserMessage="hello"
      features={features}
      availableAgentTools={toAgentTools(availableTools)}
      availableWorkspaces={availableWorkspaces}
      agentId={AGENT_ID}
    />,
    { wrapper: Wrapper },
  );

/** Background queries the real ConversationPanel stack fires on mount. */
const mountHandlers = (modelsBody = openAiOnlyModels) => [
  http.get(`${BASE_URL}/api/auth/capabilities`, () => HttpResponse.json(authDisabledCapabilities)),
  http.get(`${BASE_URL}/api/auth/me`, () => HttpResponse.json({ id: 'user-1' })),
  http.get(`${BASE_URL}/api/memory/threads/${BUILDER_THREAD_ID}/messages`, () =>
    HttpResponse.json(emptyThreadMessages),
  ),
  http.get(`${BASE_URL}/api/editor/builder/models/available`, () => HttpResponse.json(modelsBody)),
  http.get(`${BASE_URL}/api/tool-providers`, () => HttpResponse.json({ providers: [] })),
];

/** Captures the wire-serialized stream request body the panel auto-sends. */
const captureStream = () => {
  const bodies: StreamBody[] = [];
  server.use(
    ...mountHandlers(),
    http.post(`${BASE_URL}/api/agents/builder-agent/stream`, async ({ request }) => {
      bodies.push((await request.json()) as StreamBody);
      return sseResponse();
    }),
  );
  return bodies;
};

const captureStreamWith = (handlers: ReturnType<typeof mountHandlers>) => {
  const bodies: StreamBody[] = [];
  server.use(
    ...handlers,
    http.post(`${BASE_URL}/api/agents/builder-agent/stream`, async ({ request }) => {
      bodies.push((await request.json()) as StreamBody);
      return sseResponse();
    }),
  );
  return bodies;
};

const waitForSend = async (bodies: StreamBody[]) => {
  await waitFor(() => expect(bodies.length).toBeGreaterThan(0));
  return bodies[0];
};

beforeEach(() => {
  // The builder chat is local-only; suppress the thread signal subscription so
  // the only network call under test is the stream POST.
  (window as Window & { MASTRA_AGENT_SIGNALS?: string }).MASTRA_AGENT_SIGNALS = 'false';
  server.resetHandlers();
});

afterEach(() => {
  delete (window as Window & { MASTRA_AGENT_SIGNALS?: string }).MASTRA_AGENT_SIGNALS;
  cleanup();
});

describe('ConversationPanel', () => {
  describe('when rendered with the default (unfocused) composer', () => {
    it('uses the default border token styling', async () => {
      captureStream();
      const { getByTestId } = renderPanel();

      const composer = getByTestId('agent-builder-conversation-composer');
      expect(composer.className).toContain('border-border1');
      expect(composer.className).not.toContain('border-accent5Dark');
      expect(composer.className).not.toContain('focus-within:border-accent5');
    });
  });

  describe('when the panel auto-sends the starter message', () => {
    it('sends it on a builder-prefixed thread to the builder agent', async () => {
      const bodies = captureStream();
      await act(async () => {
        renderPanel();
      });

      const body = await waitForSend(bodies);
      expect(body.memory).toMatchObject({ thread: BUILDER_THREAD_ID });
    });

    it('flattens the form snapshot onto the top-level instructions field, not the visible message', async () => {
      const bodies = captureStream();
      await act(async () => {
        renderPanel({ features: { ...allOff, tools: true }, availableTools: [{ id: 'web-search' }] });
      });

      const body = await waitForSend(bodies);
      const instructions = body.instructions;
      expect(typeof instructions).toBe('string');
      expect(instructions).toContain('Current agent configuration');
      expect(instructions).toContain('"Initial"');
      const visible = JSON.stringify(body.messages ?? []);
      expect(visible).not.toContain('Current agent configuration');
    });
  });

  describe('when all features are off', () => {
    it('registers only the always-on per-field tools on the wire', async () => {
      const bodies = captureStream();
      await act(async () => {
        renderPanel();
      });

      const { clientTools = {} } = await waitForSend(bodies);
      expect(clientTools[SET_AGENT_NAME_TOOL_NAME]).toBeDefined();
      expect(clientTools[SET_AGENT_DESCRIPTION_TOOL_NAME]).toBeDefined();
      expect(clientTools[SET_AGENT_INSTRUCTIONS_TOOL_NAME]).toBeDefined();
      expect(clientTools[SET_AGENT_WORKSPACE_ID_TOOL_NAME]).toBeDefined();
    });

    it('omits every feature-gated tool on the wire', async () => {
      const bodies = captureStream();
      await act(async () => {
        renderPanel();
      });

      const { clientTools = {} } = await waitForSend(bodies);
      expect(clientTools[SET_AGENT_TOOLS_TOOL_NAME]).toBeUndefined();
      expect(clientTools[SET_AGENT_SKILLS_TOOL_NAME]).toBeUndefined();
      expect(clientTools[SET_AGENT_MODEL_TOOL_NAME]).toBeUndefined();
      expect(clientTools[SET_AGENT_BROWSER_ENABLED_TOOL_NAME]).toBeUndefined();
      expect(clientTools[CREATE_SKILL_TOOL_NAME]).toBeUndefined();
    });
  });

  describe('when features.tools is on', () => {
    it('registers the set-agent-tools tool with available tool ids in its description', async () => {
      const bodies = captureStream();
      await act(async () => {
        renderPanel({
          features: { ...allOff, tools: true },
          availableTools: [
            { id: 'web-search', description: 'Search the web' },
            { id: 'http-fetch', description: 'Fetch a URL' },
          ],
        });
      });

      const { clientTools = {} } = await waitForSend(bodies);
      const tool = clientTools[SET_AGENT_TOOLS_TOOL_NAME];
      expect(tool).toBeDefined();
      expect(tool.description).toContain('web-search');
      expect(tool.description).toContain('Search the web');
      expect(tool.description).toContain('http-fetch');
      expect(tool.description).toContain('Fetch a URL');
    });
  });

  describe('when features.model is on', () => {
    it('registers the set-agent-model tool listing only policy-allowed models', async () => {
      const bodies = captureStream();
      await act(async () => {
        renderPanel({ features: { ...allOff, model: true } });
      });

      const { clientTools = {} } = await waitForSend(bodies);
      const tool = clientTools[SET_AGENT_MODEL_TOOL_NAME];
      expect(tool).toBeDefined();
      expect(tool.description).toContain('Available models');
      expect(tool.description).toContain('provider: openai (OpenAI), name: gpt-4o');
      expect(tool.description).not.toContain('anthropic');
    });

    it('omits the set-agent-model tool when no models survive the policy filter', async () => {
      const bodies = captureStreamWith(mountHandlers({ providers: [] }));
      await act(async () => {
        renderPanel({ features: { ...allOff, model: true } });
      });

      const { clientTools = {} } = await waitForSend(bodies);
      expect(clientTools[SET_AGENT_MODEL_TOOL_NAME]).toBeUndefined();
      expect(clientTools[SET_AGENT_NAME_TOOL_NAME]).toBeDefined();
    });
  });

  describe('when features.skills is on with a workspace available', () => {
    it('registers the createSkill tool on the wire', async () => {
      const bodies = captureStream();
      await act(async () => {
        renderPanel({ features: { ...allOff, skills: true }, availableWorkspaces: [{ id: 'ws-1', name: 'Primary' }] });
      });

      const { clientTools = {} } = await waitForSend(bodies);
      expect(clientTools[CREATE_SKILL_TOOL_NAME]).toBeDefined();
      expect(clientTools[CREATE_SKILL_TOOL_NAME].id).toBe(CREATE_SKILL_TOOL_NAME);
    });

    it('omits the set-agent-skills tool when no skills are available', async () => {
      const bodies = captureStream();
      await act(async () => {
        renderPanel({ features: { ...allOff, skills: true }, availableWorkspaces: [{ id: 'ws-1', name: 'Primary' }] });
      });

      const { clientTools = {} } = await waitForSend(bodies);
      expect(clientTools[SET_AGENT_SKILLS_TOOL_NAME]).toBeUndefined();
      expect(clientTools[SET_AGENT_NAME_TOOL_NAME]).toBeDefined();
    });
  });

  describe('when features.browser is on', () => {
    it('registers the set-agent-browser-enabled tool on the wire', async () => {
      const bodies = captureStream();
      await act(async () => {
        renderPanel({ features: { ...allOff, browser: true } });
      });

      const { clientTools = {} } = await waitForSend(bodies);
      expect(clientTools[SET_AGENT_BROWSER_ENABLED_TOOL_NAME]).toBeDefined();
    });
  });
});

